export function getLocalizedDoc(slug: string, lang: string): PageData | null {
  const isIndonesian = lang === 'id' || lang.startsWith('id-') || lang.startsWith('id');
  if (!isIndonesian) return null;
  return DOCS_PAGES_ID[slug] || null;
}
